sheet.css:
.pk{--s:#e4e7ee;--d:#c3c7cd;--l:#ffffff;--ink:#2f3542;--muted:#5a6274;--accent:#3d4bd1;
  background:var(--s);color:var(--ink);
  font:500 15px/1.5 ui-sans-serif,system-ui,-apple-system,sans-serif}
[data-theme=dark].pk,[data-theme=dark] .pk{--s:#2a2d35;--d:#20232a;--l:#343842;--ink:#e8eaf0;--muted:#a8aebd}
.stage.pk{--page:var(--s);background:var(--s)}
.pk h3,.pk h4{margin:0;font-weight:600;letter-spacing:-.01em}
.pk p{margin:0}
.up{background:var(--s);border-radius:16px;box-shadow:6px 6px 18px var(--d),-6px -6px 18px var(--l)}
.up.lg{border-radius:32px;box-shadow:12px 12px 36px var(--d),-12px -12px 36px var(--l);padding:24px}
.down{background:var(--s);border-radius:16px;
  box-shadow:inset 6px 6px 12px var(--d),inset -6px -6px 12px var(--l)}
.down.lg{border-radius:32px;padding:22px}
.muted{color:var(--muted)}
.pk-btn{font:600 14px/1 inherit;background:var(--s);color:var(--ink);border:0;border-radius:16px;
  min-height:44px;padding:0 22px;cursor:pointer;
  box-shadow:6px 6px 18px var(--d),-6px -6px 18px var(--l);transition:box-shadow .14s}
.pk-btn:hover{box-shadow:4px 4px 12px var(--d),-4px -4px 12px var(--l)}
.pk-btn:active,.f-active{box-shadow:inset 6px 6px 12px var(--d),inset -6px -6px 12px var(--l)}
.pk-btn:focus-visible{outline:3px solid var(--accent);outline-offset:4px}
.pk-btn.pri{color:var(--accent)}
.pk-btn[disabled]{color:#98a0b0;cursor:not-allowed;box-shadow:3px 3px 8px var(--d),-3px -3px 8px var(--l)}
.f-hover{box-shadow:4px 4px 12px var(--d),-4px -4px 12px var(--l)!important}
.f-focus{outline:3px solid var(--accent);outline-offset:4px}
.pk-field{width:100%;background:var(--s);color:var(--ink);border:0;border-radius:16px;
  min-height:44px;padding:0 16px;font:500 15px/1.2 inherit;
  box-shadow:inset 6px 6px 12px var(--d),inset -6px -6px 12px var(--l)}
.pk-field:focus-visible{outline:3px solid var(--accent);outline-offset:4px}
.pk-label{display:block;font-size:13px;color:var(--muted);margin-bottom:8px;font-weight:600}
.pk-err{margin-top:9px;font-size:13px;font-weight:600;color:#b3261e}
[data-theme=dark] .pk-err{color:#ff9a94}
.pk-nav{display:inline-flex;gap:6px;padding:6px;border-radius:23px;background:var(--s);
  box-shadow:inset 6px 6px 12px var(--d),inset -6px -6px 12px var(--l)}
/* 44px, not 38. This pack sets a11y.targetSizeMinPx to 44 - higher than
   WCAG 2.5.8's 24 - because a neumorphic control has no border and its
   whole hit area is implied by a shadow. A 38px pill contradicted the
   pack's own declared floor. */
.pk-nav a{padding:0 18px;min-height:44px;display:inline-flex;align-items:center;border-radius:17px;
  color:var(--muted);text-decoration:none;font-weight:600;font-size:14px}
.pk-nav a[aria-current]{color:var(--ink);box-shadow:4px 4px 10px var(--d),-4px -4px 10px var(--l)}
table.pk-t{width:100%;border-collapse:collapse;font-size:14px}
table.pk-t th{text-align:left;color:var(--muted);font-size:12px;font-weight:600;padding:0 10px 10px 0}
table.pk-t td{padding:11px 10px 11px 0;color:var(--ink)}
.pk-scrim{background:rgba(47,53,66,.34);border-radius:32px;padding:34px 18px;display:flex;justify-content:center}
.pk-skel{height:12px;border-radius:8px;background:var(--s);margin-bottom:12px;
  box-shadow:inset 3px 3px 6px var(--d),inset -3px -3px 6px var(--l)}
.dial{width:96px;height:96px;border-radius:50%;background:var(--s);display:grid;place-items:center;
  box-shadow:8px 8px 20px var(--d),-8px -8px 20px var(--l)}
.dial b{font-size:24px;font-weight:600}
.swatch{border:0;border-radius:16px;height:54px;box-shadow:6px 6px 18px var(--d),-6px -6px 18px var(--l)}
